<?php $titulo_pagina='Feed da Empresa';require_once __DIR__.'/../includes/auth.php';require_once __DIR__.'/../includes/functions.php';verificarAutenticacao();if(($_SESSION['tipo_usuario']??'')!=='empresa')redirecionar('/');$stmt=$mysqli->prepare('SELECT * FROM empresas WHERE usuario_id=?');$stmt->bind_param('i',$_SESSION['usuario_id']);$stmt->execute();$empresa=$stmt->get_result()->fetch_assoc();if($_SERVER['REQUEST_METHOD']==='POST'&&validar_csrf($_POST['csrf_token']??'')){$texto=trim($_POST['conteudo']??'');$imagem=trim($_POST['imagem_url']??'');if($texto){$stmt=$mysqli->prepare('INSERT INTO publicacoes_empresas(empresa_id,conteudo,imagem_url) VALUES(?,?,?)');$stmt->bind_param('iss',$empresa['id'],$texto,$imagem);$stmt->execute();}redirecionar('/empresa/feed.php');}$stmt=$mysqli->prepare('SELECT * FROM publicacoes_empresas WHERE empresa_id=? ORDER BY criado_em DESC');$stmt->bind_param('i',$empresa['id']);$stmt->execute();$posts=$stmt->get_result()->fetch_all(MYSQLI_ASSOC);require_once __DIR__.'/../includes/header.php';?><div class="container"><div class="form-container"><h1>Feed da Empresa</h1><form method="POST"><input type="hidden" name="csrf_token" value="<?php echo token_csrf(); ?>"><div class="form-group"><label>Publicação</label><textarea name="conteudo" required></textarea></div><div class="form-group"><label>Imagem por URL</label><input name="imagem_url" type="url"></div><button class="btn">Publicar</button></form></div><div class="posts-lista"><?php foreach($posts as $post): ?><article class="post-item"><?php if($post['imagem_url']): ?><img src="<?php echo sanitizar($post['imagem_url']); ?>" style="max-width:100%" alt="Publicação empresarial"><?php endif; ?><p><?php echo nl2br(sanitizar($post['conteudo'])); ?></p></article><?php endforeach; ?></div></div><?php require_once __DIR__.'/../includes/footer.php'; ?>
